 best=(0,None)
 for pat1 in range(1,8):
  for pat2 in range(pat1,8):
   pat=np.array([[(pat1>>i)&1,(pat2>>i)&1] for i in range(3)],dtype=bool)
   nb=int(pat.sum())
   def unpack(v):
    x=v[:5];p=np.eye(5);p[:3,:3]=0;p[np.triu_indices(3,1)]=v[5:8];p[:3,:3]+=p[:3,:3].T
    p[3:,3:]=1;z=np.zeros((3,2));z[pat]=v[8:8+nb];p[:3,3:]=z;p[3:,:3]=z.T
    return x,p,v[-1]
   def con(v):
    x,p,b=unpack(v);Q=(p*x)@p;B=((1-p)*x)@(1-p);a=al*b
    return np.r_[a-Q[np.triu_indices(3,1)],a-Q.diagonal()[3:],b-B.diagonal()[:3],a-Q[:3,3:][pat],(b-B[:3,3:]).ravel()]
   for it in range(3):
    xr=rng.uniform(.001,.04,2);xb=rng.dirichlet([10]*3)*(1-sum(xr));x=np.r_[xb,xr]
    v=np.r_[x,[.525]*3,rng.uniform(.15,.3,nb),.49]
    r=minimize(lambda v:v[-1],v,method='SLSQP',bounds=[(1e-6,1)]*5+[(1e-5,1-1e-5)]*(3+nb)+[(.2,1)],constraints=[{'type':'eq','fun':lambda v:sum(v[:5])-1},{'type':'ineq','fun':con}],options={'maxiter':500,'ftol':1e-10})
    if r.success and min(con(r.x))>-1e-7 and 1/r.fun>best[0]:best=(1/r.fun,(pat1,pat2,unpack(r.x)))
 print(al,best,flush=True)

